antiPatterns.example:
// Avoid: Radios for multi-select
<RadioGroup name="tags">...</RadioGroup>

// Prefer: Checkboxes
<Checkbox /> React
<Checkbox /> TypeScript

// Avoid
<Radio name="x" value="a" />

// Prefer
<RadioGroup name="x" legend="Options">
  <RadioGroupItem value="a" label="A" />
</RadioGroup>
